 import React, { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { Link } from 'react-router-dom'
import { 
  Heart, 
  MessageCircle, 
  Globe, 
  Calendar, 
  Trophy,
  BarChart3,
  Home,
  Plane,
  Minus
} from 'lucide-react'
import VerifiedBadge from './VerifiedBadge'
import FollowButton from './follow/FollowButton'
import ProfilePicture from './ProfilePicture'
import ReactionButtons from './ReactionButtons'
import CommentSection from './CommentSection'

export default function PredictionCard({ prediction, onRefresh, currentUser }) {
    const [showComments, setShowComments] = useState(false)
    
    // Reaction state (Multi-reaction support)
    const [userReaction, setUserReaction] = useState(null)
    const [reactions, setReactions] = useState({
        like: 0,
        dislike: 0,
        laugh: 0,
        wow: 0,
        sad: 0,
        angry: 0
    })
    const [isReacting, setIsReacting] = useState(false)
    const [likesCount, setLikesCount] = useState(prediction.likes_count || 0)

    useEffect(() => {
        const getReactions = async () => {
            // Check for existing reactions on this prediction
            const { data } = await supabase
                .from('public_prediction_reactions')
                .select('type')
                .eq('prediction_id', prediction.id)

            if (data) {
                const counts = { like: 0, dislike: 0, laugh: 0, wow: 0, sad: 0, angry: 0 }
                data.forEach(r => {
                    if (counts.hasOwnProperty(r.type)) {
                        counts[r.type]++
                    }
                })
                setReactions(counts)
            }

            if (currentUser) {
                const { data: userReact } = await supabase
                    .from('public_prediction_reactions')
                    .select('type')
                    .eq('prediction_id', prediction.id)
                    .eq('user_id', currentUser.id)
                    .single()
                
                if (userReact) {
                    setUserReaction(userReact.type)
                }
            }
        }
        getReactions()
    }, [prediction.id, currentUser])

    // ✅ OPTIMISTIC REACTION HANDLER (Instant)
    const handleReaction = async (type) => {
        if (!currentUser) {
            alert('Please sign in to react')
            return
        }

        if (isReacting) return
        setIsReacting(true)

        // 1. Update local state instantly
        let newUserReaction = userReaction
        let newReactions = { ...reactions }
        let newLikesCount = likesCount

        if (userReaction === type) {
            // Un-react
            newUserReaction = null
            newReactions[type] = Math.max(0, newReactions[type] - 1)
            newLikesCount = Math.max(0, newLikesCount - 1)
        } else {
            // Change reaction
            if (userReaction) {
                newReactions[userReaction] = Math.max(0, newReactions[userReaction] - 1)
            }
            newUserReaction = type
            newReactions[type] = newReactions[type] + 1
            newLikesCount = newLikesCount + 1
        }

        // Update state immediately
        setUserReaction(newUserReaction)
        setReactions(newReactions)
        setLikesCount(newLikesCount)

        // 2. Send update to database in the background
        try {
            if (userReaction === type) {
                await supabase
                    .from('public_prediction_reactions')
                    .delete()
                    .eq('prediction_id', prediction.id)
                    .eq('user_id', currentUser.id)
            } else {
                if (userReaction) {
                    await supabase
                        .from('public_prediction_reactions')
                        .delete()
                        .eq('prediction_id', prediction.id)
                        .eq('user_id', currentUser.id)
                }

                await supabase
                    .from('public_prediction_reactions')
                    .insert({
                        prediction_id: prediction.id,
                        user_id: currentUser.id,
                        type: type
                    })
            }

            // Update the prediction's total likes in the DB
            await supabase
                .from('public_predictions')
                .update({ likes_count: newLikesCount })
                .eq('id', prediction.id)

        } catch (error) {
            console.error('Error reacting:', error)
        } finally {
            setIsReacting(false)
        }
    }

    const data = prediction.prediction_data || {}
    const homeTeam = data.homeTeam || prediction.home_team || ''
    const awayTeam = data.awayTeam || prediction.away_team || ''
    const matchName = data.matchName || prediction.match_name || ''
    
    let matchDisplay = matchName
    if (!matchDisplay && homeTeam && awayTeam) {
        matchDisplay = `${homeTeam} vs ${awayTeam}`
    }

    // Helper to get result icon
    const getResultIcon = (result) => {
        if (result === 'Home Win') return <Home size={16} className="text-green-600" />
        if (result === 'Away Win') return <Plane size={16} className="text-blue-600" />
        return <Minus size={16} className="text-gray-400" />
    }

    return (
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 hover:shadow-md transition">
            <div className="flex items-center justify-between mb-3">
                <Link to={`/profile/${prediction.profiles?.id}`} className="flex items-center gap-3 hover:opacity-80 flex-1">
                    <ProfilePicture size="md" userId={prediction.profiles?.id} />
                    <div>
                        <div className="font-semibold flex items-center gap-1.5 text-gray-800">
                            {prediction.profiles?.full_name || prediction.profiles?.username || 'Unknown'}
                            {prediction.profiles?.is_verified && <VerifiedBadge size="sm" />}
                        </div>
                        <div className="text-sm text-gray-400">@{prediction.profiles?.username || 'user'}</div>
                    </div>
                </Link>
                {prediction.user_id && prediction.user_id !== currentUser?.id && (
                    <FollowButton 
                        userId={prediction.user_id} 
                        username={prediction.profiles?.username}
                        onFollowChange={onRefresh}
                    />
                )}
            </div>

            {matchDisplay && (
                <div className="bg-gray-50 rounded-lg p-2 mb-3 border border-gray-100 text-center">
                    <div className="text-sm font-medium text-gray-700 flex items-center justify-center gap-2">
                        <Trophy size={14} className="text-gray-400" />
                        {matchDisplay}
                    </div>
                </div>
            )}

            {/* Multi-Market Prediction Layout */}
            {data.markets && data.markets.length > 0 ? (
                <div className="bg-gray-50 rounded-lg p-3 mb-3 border border-gray-100">
                    <div className="flex items-center gap-2 mb-2">
                        <BarChart3 size={16} className="text-gray-500" />
                        <span className="text-sm font-medium text-gray-700">Multi-Market Prediction</span>
                    </div>
                    <div className="space-y-1">
                        {data.markets.map((m, i) => (
                            <div key={i} className="flex justify-between text-sm text-gray-600">
                                <span>{m.label}: <strong>{m.pick}</strong></span>
                                <span className="text-gray-400">@{m.odds?.toFixed(2) || '—'}</span>
                            </div>
                        ))}
                    </div>
                    <div className="text-xs text-gray-400 text-center mt-2 flex items-center justify-center gap-1">
                        <Globe size={12} /> Public Prediction
                    </div>
                </div>
            ) : (
                /* Fallback: Old format */
                <div className="bg-gray-50 rounded-lg p-3 mb-3 border border-gray-100">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                            {getResultIcon(data.result)}
                            <span className="font-bold text-gray-800">{data.result || 'Draw'}</span>
                        </div>
                        <div className="flex items-center gap-3 text-sm text-gray-500">
                            <span>🟨 {data.yellowCards || 0}</span>
                            <span>🟥 {data.redCards || 0}</span>
                            <span>🏁 {data.corners || 0}</span>
                        </div>
                    </div>
                    <div className="text-xs text-gray-400 text-center mt-1 flex items-center justify-center gap-1">
                        <Globe size={12} /> Public Prediction
                    </div>
                </div>
            )}

            {/* ✅ REACTION BUTTONS (Now supports multiple reactions) */}
            <div className="border-t border-gray-100 pt-2 mb-3">
                <ReactionButtons onReact={handleReaction} userReaction={userReaction} reactions={reactions} />
            </div>

            {/* ✅ Comments Toggle (Now supports comments) */}
            <div className="flex items-center justify-between text-sm">
                <button 
                    onClick={() => setShowComments(!showComments)} 
                    className="flex items-center gap-1 text-gray-400 hover:text-gray-800 transition"
                >
                    <MessageCircle size={16} /> {prediction.comments?.length || 0} comments
                </button>
                <span className="text-gray-400 flex items-center gap-1">
                    <Calendar size={14} /> {new Date(prediction.created_at).toLocaleDateString()}
                </span>
            </div>

            {/* ✅ COMMENTS SECTION (Reuses your existing component) */}
            {showComments && (
                <div className="mt-3 pt-3 border-t border-gray-100">
                    <CommentSection 
                        postId={prediction.id} 
                        comments={prediction.comments || []} 
                        onRefresh={onRefresh} 
                        currentUser={currentUser}
                        postAuthorId={prediction.user_id}
                    />
                </div>
            )}
        </div>
    )
}
